package cn.haiduo;
import cn.haiduo.audit.Audit;
import cn.haiduo.platform.*;
import com.fasterxml.jackson.databind.JsonNode;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.time.*;
import java.util.*;
import jakarta.servlet.http.*;
import org.springframework.core.env.Environment;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.stereotype.Service;
import org.springframework.web.server.ResponseStatusException;
@Service public class ShopifyAuthorization {
 private final Environment env;private final JdbcTemplate db;private final ShopifyHttp http;
 @org.springframework.beans.factory.annotation.Autowired public ShopifyAuthorization(Environment env,JdbcTemplate db){this(env,db,new ShopifyHttp());} public ShopifyAuthorization(Environment env,JdbcTemplate db,ShopifyHttp http){this.env=env;this.db=db;this.http=http;}
 String required(String name){String value=env.getProperty(name);if(value==null||value.isBlank())throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Shopify连接未启用：缺少应用凭据或加密配置");return value;}
 Map<String,String> start(UUID tenant,UUID store,String shop,HttpSession session,String actor){shop=ShopifyConnector.validShop(shop);if(db.queryForObject("select count(*) from store where tenant_id=? and id=? and platform='SHOPIFY'",Integer.class,tenant,store)!=1)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"请选择Shopify店铺");if(db.queryForObject("select count(*) from platform_connection where shop_domain=? and (tenant_id<>? or store_id<>?)",Integer.class,shop,tenant,store)>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"店铺已绑定其他连接");String client=required("SHOPIFY_CLIENT_ID"),redirect=required("SHOPIFY_REDIRECT_URI");required("SHOPIFY_CLIENT_SECRET");PlatformCrypto.encrypt(required("TOKEN_ENCRYPTION_KEY"),"configuration-check");URI uri=URI.create(redirect);if(!"https".equals(uri.getScheme())&&!Set.of("localhost","127.0.0.1").contains(uri.getHost()))throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"回调地址必须HTTPS或本机地址");String state=UUID.randomUUID().toString();session.setAttribute("shopify.oauth",Map.of("tenant",tenant.toString(),"store",store.toString(),"shop",shop,"actor",actor,"state",state,"deadline",String.valueOf(Instant.now().plusSeconds(600).getEpochSecond())));return Map.of("url","https://"+shop+"/admin/oauth/authorize?client_id="+encode(client)+"&scope=read_orders&redirect_uri="+encode(redirect)+"&state="+state);}
 static String encode(String s){return URLEncoder.encode(s,StandardCharsets.UTF_8);}
 @Transactional public void callback(HttpServletRequest request,HttpSession session,String actor)throws Exception{Object value=session.getAttribute("shopify.oauth");session.removeAttribute("shopify.oauth");if(!(value instanceof Map<?,?> state))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"授权会话不存在或已使用");String shop=ShopifyConnector.validShop(request.getParameter("shop"));if(!Objects.equals(state.get("state"),request.getParameter("state"))||!Objects.equals(state.get("actor"),actor)||!Objects.equals(state.get("shop"),shop)||Long.parseLong(state.get("deadline").toString())<Instant.now().getEpochSecond())throw new ResponseStatusException(HttpStatus.FORBIDDEN,"授权状态无效");TreeMap<String,String> query=new TreeMap<>();for(var e:request.getParameterMap().entrySet()){if(e.getValue().length!=1)throw new ResponseStatusException(HttpStatus.FORBIDDEN);if(!e.getKey().equals("hmac"))query.put(e.getKey(),e.getValue()[0]);}String message=query.entrySet().stream().map(e->e.getKey()+"="+e.getValue()).collect(java.util.stream.Collectors.joining("&"));String signature=request.getParameter("hmac");byte[] received;try{received=HexFormat.of().parseHex(signature);}catch(Exception e){throw new ResponseStatusException(HttpStatus.FORBIDDEN,"授权签名无效");}if(!MessageDigest.isEqual(PlatformCrypto.hmac(required("SHOPIFY_CLIENT_SECRET"),message.getBytes(StandardCharsets.UTF_8)),received))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"授权签名无效");UUID tenant=UUID.fromString(state.get("tenant").toString()),store=UUID.fromString(state.get("store").toString());if(db.queryForObject("select count(*) from membership where tenant_id=? and username=? and role='ADMIN'",Integer.class,tenant,actor)!=1)throw new ResponseStatusException(HttpStatus.FORBIDDEN);String code=request.getParameter("code");if(code==null||code.length()>512)throw new ResponseStatusException(HttpStatus.BAD_REQUEST);JsonNode token=http.form(URI.create("https://"+shop+"/admin/oauth/access_token"),Map.of("client_id",required("SHOPIFY_CLIENT_ID"),"client_secret",required("SHOPIFY_CLIENT_SECRET"),"code",code,"expiring","1"));save(tenant,store,shop,token);db.update("update store set connection_status='CONNECTED' where tenant_id=? and id=?",tenant,store);new Audit(db).record(tenant,actor,"SHOPIFY_AUTHORIZED",store);}
 void save(UUID tenant,UUID store,String shop,JsonNode token){Set<String> scopes=new HashSet<>(Arrays.asList(token.path("scope").asText().split(",")));if(!scopes.contains("read_orders")&&!scopes.contains("write_orders"))throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"授权未包含订单读取权限");String access=token.path("access_token").asText(),refresh=token.path("refresh_token").asText();if(access.isBlank()||refresh.isBlank()||token.path("expires_in").asLong()<=0)throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"未取得可刷新离线令牌");String key=required("TOKEN_ENCRYPTION_KEY");db.update("insert into platform_connection(tenant_id,store_id,shop_domain,access_cipher,refresh_cipher,expires_at,scopes) values(?,?,?,?,?,?,?) on conflict(tenant_id,store_id) do update set shop_domain=excluded.shop_domain,access_cipher=excluded.access_cipher,refresh_cipher=excluded.refresh_cipher,expires_at=excluded.expires_at,scopes=excluded.scopes",tenant,store,shop,PlatformCrypto.encrypt(key,access),PlatformCrypto.encrypt(key,refresh),java.sql.Timestamp.from(Instant.now().plusSeconds(token.path("expires_in").asLong())),String.join(",",scopes));}
 @Transactional public ShopifyConnector connector(UUID tenant,UUID store)throws Exception{var rows=db.queryForList("select * from platform_connection where tenant_id=? and store_id=? for update",tenant,store);if(rows.isEmpty())throw new IllegalStateException("Shopify connection unavailable");var row=rows.getFirst();String shop=ShopifyConnector.validShop((String)row.get("shop_domain")),key=required("TOKEN_ENCRYPTION_KEY");var expires=(java.sql.Timestamp)row.get("expires_at");if(expires!=null&&expires.toInstant().isBefore(Instant.now().plusSeconds(60))){String refresh=PlatformCrypto.decrypt(key,(String)row.get("refresh_cipher"));JsonNode token=http.form(URI.create("https://"+shop+"/admin/oauth/access_token"),Map.of("client_id",required("SHOPIFY_CLIENT_ID"),"client_secret",required("SHOPIFY_CLIENT_SECRET"),"grant_type","refresh_token","refresh_token",refresh));save(tenant,store,shop,token);row=db.queryForMap("select * from platform_connection where tenant_id=? and store_id=?",tenant,store);}return new ShopifyConnector(URI.create("https://"+shop+"/admin/api/2026-10/graphql.json"),PlatformCrypto.decrypt(key,(String)row.get("access_cipher")),http);}
}
